import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { Truck, DollarSign, Package, Clock } from 'lucide-react';
import dispatchService from '../../services/dispatchService';
import StatCard from '../../components/ui/StatCard';

const DispatchOverview = () => {
    const { data, isLoading } = useQuery({
        queryKey: ['dispatch-dashboard'],
        queryFn: dispatchService.getDashboard
    });

    return (
        <div className="space-y-6">
            <div><h1 className="text-2xl font-bold text-brand-800 dark:text-white">Dispatch Dashboard</h1><p className="text-slate-500 mt-1">Overview of your delivery operations</p></div>
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Active Deliveries" value={data?.activeDeliveries || 0} icon={Truck} color="teal" loading={isLoading} />
                <StatCard label="Total Earnings" value={`$${(data?.totalEarnings || 0).toLocaleString()}`} icon={DollarSign} color="emerald" loading={isLoading} />
                <StatCard label="Pending" value={`$${(data?.pendingEarnings || 0).toLocaleString()}`} icon={Clock} color="gold" loading={isLoading} />
                <StatCard label="Paid" value={`$${(data?.paidEarnings || 0).toLocaleString()}`} icon={DollarSign} color="navy" loading={isLoading} />
            </div>
        </div>
    );
};

export default DispatchOverview;
